/* @lc app=leetcode id=2300 lang=kotlin */ class Solution { fun lb(a: List<Int>, v: Long): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] < v) m + 1 to hi else lo to m } }.last().first fun successfulPairs(spells: IntArray, potions: IntArray, success: Long): IntArray = potions.sorted().let { p -> spells.map { s -> p.size - lb(p, (success + s - 1) / s) }.toIntArray() } }